document.addEventListener("DOMContentLoaded",function(){const e=location.pathname.split("/").pop()||"index.html";document.querySelectorAll(".tabbar a").forEach(function(t){t.getAttribute("href")===e?t.classList.add("active"):t.classList.remove("active")}),document.querySelectorAll(".btn").forEach(function(e){"В избранное"===e.textContent.trim()&&e.addEventListener("click",function(){e.textContent="В избранное"===e.textContent.trim()?"✓ В избранном":"В избранное"})}),document.querySelectorAll(".sidebar a").forEach(function(t){t.getAttribute("href")===e&&t.classList.add("active")})});